"""Debug: exactly 26 circles"""
import numpy as np


def construct_packing():
    """Return exactly 26 circles."""
    n = 26
    centers = np.zeros((n, 2))
    radii_arr = np.zeros(n)

    # Simple grid pattern
    for i in range(n):
        row = i // 5
        col = i % 5
        centers[i] = [0.1 + col * 0.18, 0.1 + row * 0.18]
        radii_arr[i] = 0.04

    return centers, radii_arr, float(np.sum(radii_arr))


def max_possible_radius(x, y, existing):
    r = min(x, y, 1.0 - x, 1.0 - y)
    for ex, ey, er in existing:
        dist = np.sqrt((x - ex)**2 + (y - ey)**2)
        r = min(r, dist - er)
    return max(0.0, r)

